fn resolve_web_element_with_activation(
    params: Value,
    web_probe: &mut dyn WebProbeClient,
    activate: impl FnOnce(isize) -> bool,
) -> Value {
    let started = Instant::now();
    let failure = |trace: &str| web_validation_failure(5, trace, "无法定位网页元素", None);
    if !params.get("element_ref").is_some_and(Value::is_object)
        || !params
            .get("targetTabId")
            .and_then(Value::as_u64)
            .is_some_and(|id| id > 0)
        || !params
            .get("targetSessionId")
            .and_then(Value::as_str)
            .is_some_and(|id| !id.trim().is_empty())
    {
        return failure("invalid_params");
    }
    let timeout_ms = params
        .get("timeout_ms")
        .and_then(Value::as_u64)
        .unwrap_or(5000)
        .clamp(1, 60000);
    let read_geometry = params.get("read_geometry").and_then(Value::as_bool) == Some(true);
    let mut command = params;
    command["rootHwnd"] = json!(0);
    command["rootPid"] = json!(0);
    command["captureSessionId"] = json!(capture_session_id(None));
    command["action"] = json!(if read_geometry { "geometry" } else { "locate" });
    command["scrollIntoView"] = json!(!read_geometry);
    command["timeoutMs"] = json!(timeout_ms);
    let result = match execute_web_validation_probe(web_probe, &command, timeout_ms) {
        Ok(result) => result,
        Err(_) => return failure("web_bridge_unavailable"),
    };
    if value_as_i64(result.get("error")).unwrap_or(5) != 0 {
        return result;
    }
    let Some(root_hwnd) = result
        .get("provider_root_hwnd")
        .and_then(Value::as_i64)
        .filter(|hwnd| *hwnd > 0)
    else {
        return failure("browser_host_window_mismatch");
    };
    if !read_geometry && !activate(root_hwnd as isize) {
        return web_validation_failure(
            5,
            "browser_window_activation_failed",
            "无法激活浏览器窗口，已取消操作",
            None,
        );
    }
    let remaining = Duration::from_millis(timeout_ms)
        .saturating_sub(started.elapsed()).as_millis() as u64;
    let (mut result, geometry) = match execute_web_validation_with_viewport(
        web_probe, &command, remaining, Some(result),
        |evidence| resolve_browser_viewport_geometry(root_hwnd as HWND, evidence),
    ) {
        Ok(result) => result,
        Err(WebValidationAttemptError::Probe(_)) => return failure("web_bridge_unavailable"),
        Err(WebValidationAttemptError::Viewport(trace)) => return failure(trace),
    };
    if value_as_i64(result.get("error")).unwrap_or(5) != 0 {
        return result;
    }
    if result.get("provider_root_hwnd").and_then(Value::as_i64) != Some(root_hwnd) {
        return failure("browser_host_window_mismatch");
    }
    let Some(geometry) = geometry else {
        return failure("browser_viewport_evidence_missing");
    };
    let Some(evidence) = first_web_validation_evidence(&result) else {
        return failure("web_viewport_evidence_missing");
    };
    if convert_web_validation_result_to_screen(&mut result, geometry) == 0 {
        return failure("browser_viewport_conversion_failed");
    }
    let mut response = json!({"error": 0, "ok": true, "found": true, "count": 1,
        "screen_rect": result["screen_rect"], "strategy": "provider_web_dom"});
    if read_geometry {
        let dpi = unsafe { windows_sys::Win32::UI::HiDpi::GetDpiForWindow(root_hwnd as HWND) };
        let mut client_origin = POINT { x: 0, y: 0 };
        if dpi == 0 || unsafe { ClientToScreen(root_hwnd as HWND, &mut client_origin) } == 0 {
            return failure("browser_viewport_conversion_failed");
        }
        response["window_dpi"] = json!(dpi);
        response["window_client_origin"] = json!({"x": client_origin.x, "y": client_origin.y});
        response["viewport_origin"] = json!({"x": geometry.origin.0, "y": geometry.origin.1});
        response["css_scale"] = json!(evidence.scale);
    }
    response

function elementLocatePayload(element, clipOverflow) {
  if (!element || typeof element.getBoundingClientRect !== "function") return null;
  const rect = elementBoundingRect(element, element.getBoundingClientRect(), clipOverflow);
  if (!rect) return null;
  const width = rect && rect.width != null ? rect.width : Number(rect && rect.right) - Number(rect && rect.left);
  const height = rect && rect.height != null ? rect.height : Number(rect && rect.bottom) - Number(rect && rect.top);
  const clientRect = {
    x: round2(rect && rect.left),
    y: round2(rect && rect.top),
    w: Math.max(0, round2(width)),
    h: Math.max(0, round2(height))
  };
  if (clientRect.w <= 0 || clientRect.h <= 0) return null;
  const visible = visibleClientRect(rect);
  return {
    x: clientRect.x,
    y: clientRect.y,
    w: Math.max(1, clientRect.w),
    h: Math.max(1, clientRect.h),
    client_rect: clientRect,
    client_rect_space: "frame_viewport_css",
    client_rect_source: "dom_get_bounding_client_rect",
    visible_client_rect: visible,
    is_visible_in_viewport: !!visible,
    viewport_w: Number(globalThis.innerWidth) || 0,
    viewport_h: Number(globalThis.innerHeight) || 0,
    dpr: Number(globalThis.devicePixelRatio) || 1,
    frame_depth: 0
  };
}

function normalizeTransientClientRectToTopViewport(raw, context) {
  if (!raw || typeof raw !== 'object') return raw;
  const routeEvidence = context && context.routeEvidence && typeof context.routeEvidence === 'object'
    ? context.routeEvidence
    : null;
  const depth = transientFrameDepth(routeEvidence || raw);
  const localRect = transientRect(raw.client_rect || raw.clientRect);
  if (!localRect) return raw;
  const declaredSpace = transientClientRectSpace(raw);
  const screenRect = raw.screen_rect || raw.screenRect;
  const legacySpace = String(screenRect && (screenRect.coordinate_space || screenRect.coordinateSpace) || '');
  const rectSpace = declaredSpace || (legacySpace === 'viewport_client' || legacySpace === 'frame_viewport_css'
    ? 'frame_viewport_css'
    : '');

  if (rectSpace !== 'frame_viewport_css' && rectSpace !== 'top_viewport_css') {
    return unresolvedTransientFrameRect(raw, 'frame_client_rect_space_missing');
  }
  if (rectSpace === 'top_viewport_css') {
    const pageMetrics = context && context.pageMetrics;
    const viewportW = Number(pageMetrics && pageMetrics.innerWidth) || Number(raw.viewport_w || raw.viewportW) || 0;
    const viewportH = Number(pageMetrics && pageMetrics.innerHeight) || Number(raw.viewport_h || raw.viewportH) || 0;
    const normalizedScreenRect = screenRect && typeof screenRect === 'object'
      ? Object.assign({}, screenRect, {
          client_rect_space: 'top_viewport_css',
          coordinate_space: 'top_viewport_css',
          viewport_w: viewportW,
          viewport_h: viewportH,
          dpr: Number(raw.dpr) || Number(screenRect.dpr) || 1
        })
      : screenRect;
    return Object.assign({}, raw, {
      screen_rect: normalizedScreenRect,
      screenRect: normalizedScreenRect,
      client_rect_space: 'top_viewport_css',
      clientRectSpace: 'top_viewport_css',
      coordinate_space: 'top_viewport_css',
      coordinateSpace: 'top_viewport_css',
      viewport_w: viewportW,
      viewport_h: viewportH
    });
  }
  let offsetX = 0;
  let offsetY = 0;
  let topClientPoint = transientPoint(
    routeEvidence && (routeEvidence.top_client_point || routeEvidence.topClientPoint) ||
    raw.top_client_point || raw.topClientPoint
  );
  if (depth > 0 && rectSpace !== 'top_viewport_css') {
    const clientPoint = transientPoint(
      routeEvidence && (
        routeEvidence.pointer_client_point || routeEvidence.pointerClientPoint ||
        routeEvidence.client_point || routeEvidence.clientPoint
      ) ||
      raw.pointer_client_point || raw.pointerClientPoint || raw.client_point || raw.clientPoint
    );
    const clientPointSpace = String(
      routeEvidence && (
        routeEvidence.pointer_client_coordinate_space || routeEvidence.pointerClientCoordinateSpace ||
        routeEvidence.client_point_coordinate_space || routeEvidence.clientPointCoordinateSpace
      ) ||
      raw.pointer_client_coordinate_space || raw.pointerClientCoordinateSpace ||
      raw.client_point_coordinate_space || raw.clientPointCoordinateSpace || ''
    );
    if (!clientPoint || clientPointSpace !== 'frame_viewport_css') {
      return unresolvedTransientFrameRect(raw, 'frame_client_pointer_missing');
    }
    if (!topClientPoint) {
      return unresolvedTransientFrameRect(raw, 'top_client_pointer_missing');
    }
    offsetX = topClientPoint.x - clientPoint.x;
    offsetY = topClientPoint.y - clientPoint.y;
  }
  const topRect = translateTransientRect(localRect, offsetX, offsetY);
  const localVisible = transientRect(raw.visible_client_rect || raw.visibleClientRect);
  const topVisible = localVisible ? translateTransientRect(localVisible, offsetX, offsetY) : null;
  if (!topRect) return unresolvedTransientFrameRect(raw, 'frame_client_rect_invalid');

  const pageMetrics = context && context.pageMetrics;
  const viewportW = Number(pageMetrics && pageMetrics.innerWidth) || Number(raw.viewport_w || raw.viewportW) || 0;
  const viewportH = Number(pageMetrics && pageMetrics.innerHeight) || Number(raw.viewport_h || raw.viewportH) || 0;

  const normalizedScreenRect = screenRect && typeof screenRect === 'object'
    ? Object.assign({}, screenRect, {
        x: topRect.x,
        y: topRect.y,
        w: topRect.w,
        h: topRect.h,
        frame_local_client_rect: localRect,
        client_rect: topRect,
        visible_client_rect: topVisible || undefined,
        client_rect_space: 'top_viewport_css',
        coordinate_space: 'top_viewport_css',
        viewport_w: viewportW,
        viewport_h: viewportH,
        dpr: Number(raw.dpr) || 1
      })
    : screenRect;
  return Object.assign({}, raw, {
